/**
 * Deterministic rule-based fallback assistant.
 * Analyzes English and Hindi inputs with keyword heuristics and domain matrices.
 */
export function generateRuleBasedSuggestion(request: ComplaintAssistantRequest): ComplaintAssistantSuggestion {
  const queryLower = (request.query || request.currentDescription || "").toLowerCase();
  const sector = request.sector || "Greater Noida";

  // Find best matching category based on keyword hits
  let matchedRule = CATEGORY_RULES[1]!; // Default to Road Surface
  let maxScore = 0;

  for (const rule of CATEGORY_RULES) {
    let score = 0;
    for (const kw of rule.keywords) {
      if (queryLower.includes(kw.toLowerCase())) {
        score += 2;
      }
    }
    // Boost if user had already selected this category
    if (request.currentCategory && request.currentCategory.toLowerCase() === rule.category.toLowerCase()) {
      score += 1;
    }
    if (score > maxScore) {
      maxScore = score;
      matchedRule = rule;
    }
  }

  // Find matching authority
  const authority =
    OFFICIAL_AUTHORITIES.find((a) => a.id === matchedRule.authorityId) || OFFICIAL_AUTHORITIES[0]!;

  // Determine severity based on critical phrases
  let severity: "critical" | "high" | "medium" | "low" = matchedRule.defaultSeverity;
  let severityReason = `Standard baseline severity for ${matchedRule.category} category.`;

  if (
    queryLower.includes("accident") ||
    queryLower.includes("crash") ||
    queryLower.includes("gir gaya") ||
    queryLower.includes("ambulance") ||
    queryLower.includes("danger") ||
    queryLower.includes("open manhole") ||
    queryLower.includes("immediate")
  ) {
    severity = "critical";
    severityReason = "Escalated to Critical because incident details indicate immediate collision or pedestrian fall hazard.";
  } else if (
    queryLower.includes("deep") ||
    queryLower.includes("huge") ||
    queryLower.includes("bada") ||
    queryLower.includes("heavy traffic") ||
    queryLower.includes("expressway") ||
    queryLower.includes("highway")
  ) {
    severity = "high";
    severityReason = "Classified as High Urgency due to structural size and primary roadway flow impact.";
  }

  // Format clean title
  const rawClean = (request.query || request.currentDescription || "")
    .replace(/[^\w\s\u0900-\u097F-]/g, " ")
    .trim()
    .slice(0, 70);

  const suggestedTitle = rawClean.length > 5
    ? `${matchedRule.category.split("/")[0]?.trim() || "Hazard"}: ${rawClean} (${sector})`
    : `${matchedRule.category.split("/")[0]?.trim() || "Road Hazard"} reported near ${sector}`;

  // Improve description
  const originalTrimmed = (request.query || request.currentDescription || "").trim();
  const improvedDescription = originalTrimmed.length > 10
    ? `Citizen reported ${matchedRule.category.toLowerCase()} hazard in the vicinity of ${sector}. Observation: "${originalTrimmed}". Physical defect poses potential vehicular and pedestrian risk requiring municipal inspection.`
    : `Hazard observed in ${sector}: ${matchedRule.category}. Prompt municipal site inspection requested for commuter safety.`;

  return {
    suggestedTitle: suggestedTitle.slice(0, 100),
    suggestedCategory: matchedRule.category,
    improvedDescription,
    suggestedEvidence: matchedRule.evidenceSuggestions,
    suggestedDepartment: {
      id: authority.id,
      name: authority.name,
      jurisdiction: authority.jurisdiction,
      slaDays: authority.slaDays,
    },
    suggestedSeverity: severity,
    priorityReasoning: severityReason,
    isAIGenerated: false,
    provider: "rule-based-fallback",
    disclaimer: DISCLAIMER_TEXT,
  };
}

/**
 * Main Assistant entrypoint.
 * Attempts LLM synthesis via OpenRouter if configured, otherwise falls back smoothly.
 */
export async function assistComplaintDrafting(
  request: ComplaintAssistantRequest
): Promise<ComplaintAssistantSuggestion> {
  const apiKey = process.env.OPENROUTER_API_KEY;
  const model = process.env.OPENROUTER_MODEL || "google/gemini-2.0-flash-001";
  const baseUrl = process.env.OPENROUTER_BASE_URL || "https://openrouter.ai/api/v1";

  if (!apiKey || apiKey.includes("placeholder") || apiKey.trim().length < 10) {
    return generateRuleBasedSuggestion(request);
  }

  try {
    const prompt = `
You are the AI Complaint Drafting Assistant for JanSahayak SafeStreets (Greater Noida, India).
A citizen is reporting a road safety or municipal infrastructure hazard in either English, Hindi, or Hinglish.
Citizen input: "${request.query || request.currentDescription || ""}"
Current category selection (if any): "${request.currentCategory || "None"}"
Location sector: "${request.sector || "Greater Noida"}"

Official Department Options:
${JSON.stringify(OFFICIAL_AUTHORITIES, null, 2)}

Approved Categories:
1. "Road Surface / Pothole"
2. "Broken Footpath / Pavement"
3. "Street Lighting / Darkness"
4. "Drainage / Manhole"
5. "Unsafe Crossing / Signals"
6. "Visibility / Obstruction"

Return a strictly valid JSON object conforming to:
{
  "suggestedTitle": "Short, objective, informative title (e.g. Deep Pothole Damage Near Pari Chowk)",
  "suggestedCategory": "One exact approved category string",
  "improvedDescription": "Clear, professional, and helpful description preserving the citizen's original intent without inventing facts",
  "suggestedEvidence": ["4 concise suggestions for helpful photographic/location evidence"],
  "suggestedDepartmentId": "One exact id from Official Department Options",
  "suggestedSeverity": "critical" | "high" | "medium" | "low",
  "priorityReasoning": "Transparent rationale for severity score"
}
`;

    const res = await fetch(`${baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        "HTTP-Referer": process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000",
        "X-Title": "JanSahayak SafeStreets",
      },
      body: JSON.stringify({
        model,
        response_format: { type: "json_object" },
        messages: [{ role: "user", content: prompt }],
        temperature: 0.2,
        max_tokens: 800,
      }),
    });

    if (!res.ok) {
      throw new Error(`OpenRouter returned status ${res.status}`);
    }

    const data = await res.json();
    const content = data.choices?.[0]?.message?.content || "{}";
    const parsed = JSON.parse(content);

    const authority =
      OFFICIAL_AUTHORITIES.find((a) => a.id === parsed.suggestedDepartmentId) ||
      OFFICIAL_AUTHORITIES[0]!;

    return {
      suggestedTitle: parsed.suggestedTitle || "Road Hazard Report",
      suggestedCategory: parsed.suggestedCategory || "Road Surface / Pothole",
      improvedDescription: parsed.improvedDescription || request.query || "",
      suggestedEvidence: Array.isArray(parsed.suggestedEvidence) && parsed.suggestedEvidence.length > 0
        ? parsed.suggestedEvidence
        : CATEGORY_RULES[1]!.evidenceSuggestions,
      suggestedDepartment: {
        id: authority.id,
        name: authority.name,
        jurisdiction: authority.jurisdiction,
        slaDays: authority.slaDays,
      },
      suggestedSeverity: parsed.suggestedSeverity || "medium",
      priorityReasoning: parsed.priorityReasoning || "Evaluated by AI complaint assistant based on reported physical hazard impact.",
      isAIGenerated: true,
      provider: "openrouter",
      modelUsed: model,
      disclaimer: DISCLAIMER_TEXT,
    };
  } catch (error) {
    console.warn("AI Assistant OpenRouter call failed, using rule-based fallback:", error);
    return generateRuleBasedSuggestion(request);
  }
}

/**
 * Convenience helper for direct text queries and automated testing.
 */
export async function generateComplaintSuggestions(input: string, lang: string = "auto") {
  const result = await assistComplaintDrafting({ query: input, language: lang as any });
  const cat = result.suggestedCategory.toLowerCase();
  const normalizedCategory =
    cat.includes("pothole") || cat.includes("road")
      ? "road-surface"
      : cat.includes("light")
      ? "lighting"
      : cat.includes("drain") || cat.includes("water")
      ? "drainage"
      : cat.includes("crossing") || cat.includes("signal")
      ? "crossing"
      : cat.includes("footpath") || cat.includes("pavement")
      ? "footpath"
      : "other";

  return {
    suggestedCategory: normalizedCategory,
    structuredTitle: result.suggestedTitle,
    suggestedDepartment: result.suggestedDepartment.name,
    suggestedPriority: result.suggestedSeverity,
    evidenceSuggestions: result.suggestedEvidence,
    improvedDescription: result.improvedDescription,
    isAiGenerated: result.isAIGenerated,
  };
}
